private void showExitDialog(){ AlertDialog.Builder b=new AlertDialog.Builder(this); b.setTitle("Exit Room?"); b.setMessage("Exit room or Minimize to Home?"); b.setPositiveButton("Exit Room",(d,w)->{ leaveRoomAndFinish(); finishAffinity(); }); b.setNeutralButton("Minimize",(d,w)->{ leaveRoomKeepHome(); finish(); }); b.setNegativeButton("Cancel",(d,w)->d.dismiss()); b.show(); }
private void leaveRoomKeepHome(){ for(int i=0;i<10;i++){ final int idx=i; databaseReference.child("seats").child("seat_"+idx).addListenerForSingleValueEvent(new ValueEventListener(){ @Override public void onDataChange(@NonNull DataSnapshot s){ String uid=s.child("userId").getValue(String.class); if(uid!=null&&uid.equals(currentUserId)) databaseReference.child("seats").child("seat_"+idx).removeValue(); } @Override public void onCancelled(@NonNull DatabaseError e){} }); } }
private void leaveRoomAndFinish(){ databaseReference.child("online_users").child(currentUserId).removeValue(); for(int i=0;i<10;i++){ final int idx=i; databaseReference.child("seats").child("seat_"+idx).addListenerForSingleValueEvent(new ValueEventListener(){ @Override public void onDataChange(@NonNull DataSnapshot s){ String uid=s.child("userId").getValue(String.class); if(uid!=null&&uid.equals(currentUserId)) databaseReference.child("seats").child("seat_"+idx).removeValue(); } @Override public void onCancelled(@NonNull DatabaseError e){} }); } finish(); }
private void listenToMyWallet(){ if(currentUserId.isEmpty()) return; userDatabaseRef.child(currentUserId).addValueEventListener(new ValueEventListener(){ @Override public void onDataChange(@NonNull DataSnapshot s){ Long coins=s.child("coins").getValue(Long.class); Long avail=s.child("availableBalance").getValue(Long.class); Long bal=s.child("balance").getValue(Long.class); Long oldW=s.child("walletCoins").getValue(Long.class); long w=0L; if(coins!=null) w=coins; else if(avail!=null) w=avail; else if(bal!=null) w=bal; else if(oldW!=null) w=oldW; myWalletCoins=w; if(walletTextInGift!=null) walletTextInGift.setText(formatCoins(w)); } @Override public void onCancelled(@NonNull DatabaseError e){} }); }
private String formatCoins(long v){ return String.format("%,d",v); }
private void deductMyCoins(long totalCost){ userDatabaseRef.child(currentUserId).child("coins").addListenerForSingleValueEvent(new ValueEventListener(){ @Override public void onDataChange(@NonNull DataSnapshot s){ Long cur=s.getValue(Long.class); long now=(cur!=null?cur:0L)-totalCost; if(now<0) now=0; userDatabaseRef.child(currentUserId).child("coins").setValue(now); userDatabaseRef.child(currentUserId).child("walletCoins").setValue(now); userDatabaseRef.child(currentUserId).child("availableBalance").setValue(now); myWalletCoins=now; if(walletTextInGift!=null) walletTextInGift.setText(formatCoins(now)); } @Override public void onCancelled(@NonNull DatabaseError e){} }); userDatabaseRef.child(currentUserId).child("sendingCoins").addListenerForSingleValueEvent(new ValueEventListener(){ @Override public void onDataChange(@NonNull DataSnapshot s){ Long cur=s.getValue(Long.class); userDatabaseRef.child(currentUserId).child("sendingCoins").setValue((cur!=null?cur:0L)+totalCost); } @Override public void onCancelled(@NonNull DatabaseError e){} }); }
private void addReceiverCoins30(String targetUid,long receiverGets){ userDatabaseRef.child(targetUid).child("coins").addListenerForSingleValueEvent(new ValueEventListener(){ @Override public void onDataChange(@NonNull DataSnapshot s){ Long cur=s.getValue(Long.class); long now=(cur!=null?cur:0L)+receiverGets; userDatabaseRef.child(targetUid).child("coins").setValue(now); userDatabaseRef.child(targetUid).child("walletCoins").setValue(now); userDatabaseRef.child(targetUid).child("availableBalance").setValue(now); } @Override public void onCancelled(@NonNull DatabaseError e){} }); userDatabaseRef.child(targetUid).child("receivingCoins").addListenerForSingleValueEvent(new ValueEventListener(){ @Override public void onDataChange(@NonNull DataSnapshot s){ Long cur=s.getValue(Long.class); userDatabaseRef.child(targetUid).child("receivingCoins").setValue((cur!=null?cur:0L)+receiverGets); } @Override public void onCancelled(@NonNull DatabaseError e){} }); }
private void handleSelfSend(long totalCost,long receiverGets){ userDatabaseRef.child(currentUserId).child("coins").addListenerForSingleValueEvent(new ValueEventListener(){ @Override public void onDataChange(@NonNull DataSnapshot s){ Long cur=s.getValue(Long.class); long base=(cur!=null?cur:0L); long now=base-totalCost+receiverGets; if(now<0) now=0; userDatabaseRef.child(currentUserId).child("coins").setValue(now); userDatabaseRef.child(currentUserId).child("walletCoins").setValue(now); userDatabaseRef.child(currentUserId).child("availableBalance").setValue(now); myWalletCoins=now; if(walletTextInGift!=null) walletTextInGift.setText(formatCoins(now)); } @Override public void onCancelled(@NonNull DatabaseError e){} }); userDatabaseRef.child(currentUserId).child("sendingCoins").addListenerForSingleValueEvent(new ValueEventListener(){ @Override public void onDataChange(@NonNull DataSnapshot s){ Long cur=s.getValue(Long.class); userDatabaseRef.child(currentUserId).child("sendingCoins").setValue((cur!=null?cur:0L)+totalCost); } @Override public void onCancelled(@NonNull DatabaseError e){} }); userDatabaseRef.child(currentUserId).child("receivingCoins").addListenerForSingleValueEvent(new ValueEventListener(){ @Override public void onDataChange(@NonNull DataSnapshot s){ Long cur=s.getValue(Long.class); userDatabaseRef.child(currentUserId).child("receivingCoins").setValue((cur!=null?cur:0L)+receiverGets); } @Override public void onCancelled(@NonNull DatabaseError e){} }); }
