private void showQuantityPopup(Button btnQtyPopup,GiftModel selectedGift){ AlertDialog.Builder qb=new AlertDialog.Builder(this); qb.setTitle("Select Quantity (1 to 10)"); LinearLayout layout=new LinearLayout(this); layout.setOrientation(LinearLayout.VERTICAL); layout.setPadding(40,30,40,20); TextView label=new TextView(this); label.setText("Select 1, 3, 5, 10 or type below"); label.setTextSize(13); label.setGravity(Gravity.CENTER); label.setPadding(0,0,0,15); layout.addView(label); LinearLayout row=new LinearLayout(this); row.setOrientation(LinearLayout.HORIZONTAL); row.setGravity(Gravity.CENTER); int[] presets={1,3,5,10}; for(int q:presets){ Button b=new Button(this); b.setText("x"+q); b.setTypeface(null,android.graphics.Typeface.BOLD); LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(0,ViewGroup.LayoutParams.WRAP_CONTENT,1f); lp.setMargins(6,0,6,0); b.setLayoutParams(lp); b.setBackgroundColor(q==giftQuantity?Color.parseColor("#FFD700"):Color.parseColor("#2A1B4E")); b.setTextColor(q==giftQuantity?Color.BLACK:Color.WHITE); row.addView(b); } layout.addView(row); TextView cl=new TextView(this); cl.setText("Custom - Type yourself (1 to 10):"); cl.setTextSize(13); cl.setPadding(0,20,0,8); layout.addView(cl); EditText inputCustom=new EditText(this); inputCustom.setHint("Ex: 2, 4, 6, 7, 8, 9..."); inputCustom.setInputType(android.text.InputType.TYPE_CLASS_NUMBER); inputCustom.setTextColor(Color.BLACK); inputCustom.setBackgroundColor(Color.WHITE); inputCustom.setPadding(25,20,25,20); layout.addView(inputCustom); qb.setView(layout); qb.setPositiveButton("OK - Custom Apply",(d,w)->{ String txt=inputCustom.getText().toString().trim(); if(!txt.isEmpty()){ try{ int cq=Integer.parseInt(txt); if(cq<1) cq=1; if(cq>10){ Toast.makeText(this,"Max 10 allowed!",Toast.LENGTH_SHORT).show(); cq=10; } giftQuantity=cq; btnQtyPopup.setText("x"+giftQuantity); if(selectedGift!=null) triggerFlyingGiftAnimation(selectedGift.getGiftName()+" x"+giftQuantity); }catch(Exception e){ Toast.makeText(this,"Enter correct number!",Toast.LENGTH_SHORT).show(); } } }); qb.setNegativeButton("Cancel",(d,w)->d.dismiss()); AlertDialog dialog=qb.create(); dialog.show(); for(int i=0;i<row.getChildCount();i++){ View child=row.getChildAt(i); if(child instanceof Button){ Button bb=(Button)child; bb.setOnClickListener(v->{ String t=bb.getText().toString().replace("x",""); try{ giftQuantity=Integer.parseInt(t); }catch(Exception ignored){} btnQtyPopup.setText("x"+giftQuantity); if(selectedGift!=null) triggerFlyingGiftAnimation(selectedGift.getGiftName()+" x"+giftQuantity); dialog.dismiss(); }); } } }
private void showNewGiftPanel(){ BottomSheetDialog dialog=new BottomSheetDialog(this,R.style.Theme_Design_BottomSheetDialog); LinearLayout root=new LinearLayout(this); root.setOrientation(LinearLayout.VERTICAL); root.setPadding(30,20,30,20); GradientDrawable bg=new GradientDrawable(GradientDrawable.Orientation.TOP_BOTTOM,new int[]{Color.parseColor("#1B1035"),Color.parseColor("#0A0518")}); bg.setCornerRadii(new float[]{45,45,45,45,0,0,0,0}); root.setBackground(bg); TextView title=new TextView(this); title.setText("Gift Center"); title.setTextColor(Color.parseColor("#FFD700")); title.setTextSize(18); title.setTypeface(null,android.graphics.Typeface.BOLD); title.setGravity(Gravity.CENTER); title.setPadding(0,0,0,12); root.addView(title); TextView targetInfo=new TextView(this); targetInfo.setText("To: "+selectedGiftTargetName+" - Tap a seat user below"); targetInfo.setTextColor(Color.WHITE); targetInfo.setTextSize(13); targetInfo.setGravity(Gravity.CENTER); targetInfo.setPadding(0,0,0,10); root.addView(targetInfo); HorizontalScrollView seatScroll=new HorizontalScrollView(this); seatScroll.setLayoutParams(new LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT,180)); LinearLayout seatRow=new LinearLayout(this); seatRow.setOrientation(LinearLayout.HORIZONTAL); seatRow.setGravity(Gravity.CENTER_VERTICAL); seatRow.addView(makeSeatAvatarView("All","All",null,targetInfo,true)); databaseReference.child("seats").addListenerForSingleValueEvent(new ValueEventListener(){ @Override public void onDataChange(@NonNull DataSnapshot snap){ for(int i=0;i<10;i++){ String k="seat_"+i; if(!snap.hasChild(k)) continue; String n=snap.child(k).child("userName").getValue(String.class); String uid=snap.child(k).child("userId").getValue(String.class); String img=snap.child(k).child("userImage").getValue(String.class); if(n==null||n.isEmpty()||uid==null) continue; seatRow.addView(makeSeatAvatarView(n,uid,img,targetInfo,false)); } } @Override public void onCancelled(@NonNull DatabaseError e){} }); seatScroll.addView(seatRow); root.addView(seatScroll); HorizontalScrollView catScroll=new HorizontalScrollView(this); catScroll.setLayoutParams(new LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT,110)); LinearLayout catRow=new LinearLayout(this); catRow.setOrientation(LinearLayout.HORIZONTAL); String[] cats={"Gift","Lucky","CP","Activity","Flag","Exclusive","Bag"}; List<Button> catBtns=new ArrayList<>(); RecyclerView rv=new RecyclerView(this); rv.setLayoutManager(new GridLayoutManager(this,4)); rv.setLayoutParams(new LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT,650)); final GiftModel[] holder={getGiftsForCategory("Gift").get(0)}; Runnable refreshGifts=()->{ List<GiftModel> list=getGiftsForCategory(giftCategory); GiftAdapter ad=new GiftAdapter(list,gift->{ holder[0]=gift; }); rv.setAdapter(ad); for(Button b:catBtns){ boolean sel=b.getText().toString().equals(giftCategory); b.setBackgroundColor(sel?Color.parseColor("#FFD700"):Color.parseColor("#2A1B4E")); b.setTextColor(sel?Color.BLACK:Color.WHITE); } }; for(String c:cats){ Button b=new Button(this); b.setText(c); b.setTextSize(12); b.setTypeface(null,android.graphics.Typeface.BOLD); LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(ViewGroup.LayoutParams.WRAP_CONTENT,ViewGroup.LayoutParams.WRAP_CONTENT); lp.setMargins(0,0,8,0); b.setLayoutParams(lp); b.setOnClickListener(v->{ giftCategory=c; refreshGifts.run(); }); catRow.addView(b); catBtns.add(b); } catScroll.addView(catRow); root.addView(catScroll); root.addView(rv); refreshGifts.run(); LinearLayout bottomBar=new LinearLayout(this); bottomBar.setOrientation(LinearLayout.HORIZONTAL); bottomBar.setGravity(Gravity.CENTER_VERTICAL); bottomBar.setPadding(0,15,0,5); walletTextInGift=new TextView(this); walletTextInGift.setText(formatCoins(myWalletCoins)); walletTextInGift.setTextColor(Color.parseColor("#00E676")); walletTextInGift.setTextSize(14); walletTextInGift.setTypeface(null,android.graphics.Typeface.BOLD); walletTextInGift.setPadding(20,15,20,15); GradientDrawable wBg=new GradientDrawable(); wBg.setColor(Color.parseColor("#2A1B4E")); wBg.setCornerRadius(25); walletTextInGift.setBackground(wBg); bottomBar.addView(walletTextInGift); Button btnSend=new Button(this); btnSend.setText("SEND"); btnSend.setBackgroundColor(Color.parseColor("#FF4081")); btnSend.setTextColor(Color.WHITE); btnSend.setTypeface(null,android.graphics.Typeface.BOLD); btnSend.setTextSize(16); LinearLayout.LayoutParams sendLp=new LinearLayout.LayoutParams(0,130,1f); sendLp.setMargins(12,0,12,0); btnSend.setLayoutParams(sendLp); bottomBar.addView(btnSend); Button btnQtyBottom=new Button(this); btnQtyBottom.setText("x"+giftQuantity); btnQtyBottom.setBackgroundColor(Color.parseColor("#FFD700")); btnQtyBottom.setTextColor(Color.BLACK); btnQtyBottom.setTypeface(null,android.graphics.Typeface.BOLD); btnQtyBottom.setPadding(18,12,18,12); btnQtyBottom.setOnClickListener(v->showQuantityPopup(btnQtyBottom,holder[0])); bottomBar.addView(btnQtyBottom); root.addView(bottomBar); btnSend.setOnClickListener(v->{ if(holder[0]==null) return; String priceStr=holder[0].getGiftPrice().replaceAll("[^0-9]",""); long onePrice=priceStr.isEmpty()?20L:Long.parseLong(priceStr); long totalCost=onePrice*giftQuantity; long receiverGets=(long)(totalCost*EXCHANGE_RATE); if(receiverGets<=0&&totalCost>0) receiverGets=1; if(myWalletCoins<totalCost){ Toast.makeText(this,"Low balance! Need "+formatCoins(totalCost)+", Have "+formatCoins(myWalletCoins),Toast.LENGTH_LONG).show(); return; } boolean isSelf=!selectedGiftTargetUid.isEmpty()&&!selectedGiftTargetUid.equals("All")&&selectedGiftTargetUid.equals(currentUserId); if(isSelf){ handleSelfSend(totalCost,receiverGets); } else { deductMyCoins(totalCost); if(selectedGiftTargetUid.equals("")||selectedGiftTargetUid.equals("All")){ databaseReference.child("seats").addListenerForSingleValueEvent(new ValueEventListener(){ @Override public void onDataChange(@NonNull DataSnapshot snap){ for(int i=0;i<10;i++){ String k="seat_"+i; if(snap.hasChild(k)){ Long cur=snap.child(k).child("giftTotal").getValue(Long.class); databaseReference.child("seats").child(k).child("giftTotal").setValue((cur!=null?cur:0L)+receiverGets); String sid=snap.child(k).child("userId").getValue(String.class); if(sid!=null&&!sid.isEmpty()){ if(sid.equals(currentUserId)){ userDatabaseRef.child(sid).child("coins").addListenerForSingleValueEvent(new ValueEventListener(){ @Override public void onDataChange(@NonNull DataSnapshot s2){ Long cc=s2.getValue(Long.class); userDatabaseRef.child(sid).child("coins").setValue((cc!=null?cc:0L)+receiverGets); } @Override public void onCancelled(@NonNull DatabaseError e){} }); } else addReceiverCoins30(sid,receiverGets); } } } } @Override public void onCancelled(@NonNull DatabaseError e){} }); } else { final String targetUid=selectedGiftTargetUid; databaseReference.child("seats").addListenerForSingleValueEvent(new ValueEventListener(){ @Override public void onDataChange(@NonNull DataSnapshot snap){ for(int i=0;i<10;i++){ String k="seat_"+i; if(snap.hasChild(k)&&targetUid.equals(snap.child(k).child("userId").getValue(String.class))){ Long cur=snap.child(k).child("giftTotal").getValue(Long.class); databaseReference.child("seats").child(k).child("giftTotal").setValue((cur!=null?cur:0L)+receiverGets); } } } @Override public void onCancelled(@NonNull DatabaseError e){} }); addReceiverCoins30(targetUid,receiverGets); } } triggerFlyingGiftAnimation(holder[0].getGiftName()+" x"+giftQuantity); String userName=prefs.getString("USER_NAME","User"); String msgId=messagesRef.push().getKey(); if(msgId!=null){ Map<String,Object> m=new HashMap<>(); m.put("senderName",getCorrectBadgeIcon(currentUserId)+userName); m.put("message","sent gift ["+holder[0].getGiftName()+" x"+giftQuantity+" - Sent: "+formatCoins(totalCost)+" | Receiver Gets: "+formatCoins(receiverGets)+" (30% Exchange)] to "+selectedGiftTargetName); m.put("timestamp",System.currentTimeMillis()); messagesRef.child(msgId).setValue(m); } Toast.makeText(this,"Sent: "+formatCoins(totalCost)+" | "+selectedGiftTargetName+" Gets: "+formatCoins(receiverGets)+" (30%)",Toast.LENGTH_LONG).show(); dialog.dismiss(); }); dialog.setContentView(root); Window w=dialog.getWindow(); if(w!=null){ int sh=getResources().getDisplayMetrics().heightPixels; w.setLayout(ViewGroup.LayoutParams.MATCH_PARENT,(int)(sh*0.67)); w.setGravity(Gravity.BOTTOM); } dialog.show(); }
private View makeSeatAvatarView(String name,String uid,String imgBase64,TextView targetInfo,boolean isAll){ LinearLayout col=new LinearLayout(this); col.setOrientation(LinearLayout.VERTICAL); col.setGravity(Gravity.CENTER); col.setPadding(12,8,12,8); ImageView av=new ImageView(this); LinearLayout.LayoutParams ap=new LinearLayout.LayoutParams(110,110); av.setLayoutParams(ap); av.setScaleType(ImageView.ScaleType.CENTER_CROP); if(imgBase64!=null&&!imgBase64.isEmpty()){ try{ byte[] b=android.util.Base64.decode(imgBase64,android.util.Base64.DEFAULT); Bitmap bmp=BitmapFactory.decodeByteArray(b,0,b.length); if(bmp!=null){ RoundedBitmapDrawable d=RoundedBitmapDrawableFactory.create(getResources(),bmp); d.setCircular(true); av.setImageDrawable(d); } else av.setImageResource(android.R.drawable.ic_menu_my_calendar); }catch(Exception e){ av.setImageResource(android.R.drawable.ic_menu_my_calendar); } } else av.setImageResource(android.R.drawable.ic_menu_my_calendar); col.addView(av); TextView nt=new TextView(this); nt.setText(name.length()>8?name.substring(0,8):name); nt.setTextColor(Color.WHITE); nt.setTextSize(11); nt.setGravity(Gravity.CENTER); col.addView(nt); col.setOnClickListener(v->{ selectedGiftTargetUid=isAll?"":uid; selectedGiftTargetName=name; if(targetInfo!=null) targetInfo.setText("To: "+name+" - Selected"); Toast.makeText(this,"Selected: "+name,Toast.LENGTH_SHORT).show(); }); return col; }
private List<GiftModel> getGiftsForCategory(String cat){ List<GiftModel> list=new ArrayList<>(); if(cat.equals("Gift")){ list.add(new GiftModel("g1","Rose","20",R.drawable.ic_gift_flower,"Gift")); list.add(new GiftModel("g2","Kiss","66",R.drawable.ic_gift_ring,"Gift")); list.add(new GiftModel("g3","Love","100",R.drawable.ic_gift_diamond,"Gift")); list.add(new GiftModel("g4","Cake","199",R.drawable.ic_gift_car,"Gift")); list.add(new GiftModel("g5","Crown","500",R.drawable.ic_gift_crown,"Gift")); list.add(new GiftModel("g6","Diamond","9999",R.drawable.ic_gift_castle,"Gift")); } else if(cat.equals("Lucky")){ list.add(new GiftModel("l1","Lucky Star","20",R.drawable.ic_gift_flower,"Lucky")); list.add(new GiftModel("l2","Lucky 7","77",R.drawable.ic_gift_ring,"Lucky")); list.add(new GiftModel("l3","Lucky Wheel","777",R.drawable.ic_gift_diamond,"Lucky")); } else if(cat.equals("CP")){ list.add(new GiftModel("c1","CP Heart","99999",R.drawable.ic_gift_flower,"CP")); list.add(new GiftModel("c2","CP Ring","9999",R.drawable.ic_gift_ring,"CP")); } else if(cat.equals("Activity")){ list.add(new GiftModel("a1","Birthday Cake","9999",R.drawable.ic_gift_flower,"Activity")); list.add(new GiftModel("a2","Party","999",R.drawable.ic_gift_car,"Activity")); } else if(cat.equals("Flag")){ list.add(new GiftModel("f1","Flag","50",R.drawable.ic_gift_flower,"Flag")); list.add(new GiftModel("f2","Country Flag","100",R.drawable.ic_gift_ring,"Flag")); } else if(cat.equals("Exclusive")){ list.add(new GiftModel("e1","Exclusive Dragon","250000",R.drawable.ic_gift_diamond,"Exclusive")); list.add(new GiftModel("e2","Exclusive Crown","1000000",R.drawable.ic_gift_crown,"Exclusive")); } else if(cat.equals("Bag")){ list.add(new GiftModel("b1","Gift Bag","500",R.drawable.ic_gift_castle,"Bag")); list.add(new GiftModel("b2","Luxury Bag","5000",R.drawable.ic_gift_car,"Bag")); } else { list.add(new GiftModel("g1","White Tiger","50000",R.drawable.ic_gift_flower,"Animal")); } return list; }
private void setupThemeBackgroundImage(){ try{ ViewGroup root=findViewById(android.R.id.content); if(root==null) return; themeBackgroundImg=new ImageView(this); themeBackgroundImg.setScaleType(ImageView.ScaleType.CENTER_CROP); themeBackgroundImg.setAlpha(0.85f); FrameLayout.LayoutParams lp=new FrameLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT,ViewGroup.LayoutParams.MATCH_PARENT); root.addView(themeBackgroundImg,0); if(root.getChildCount()>1) root.getChildAt(1).bringToFront(); }catch(Exception ignored){} }
private void applyRoomTheme(String c1,String c2,String fullText,String imageName){ try{ currentThemeName=fullText; int resId=getResources().getIdentifier(imageName,"drawable",getPackageName()); if(themeBackgroundImg!=null){ if(resId!=0){ themeBackgroundImg.setImageResource(resId); themeBackgroundImg.setVisibility(View.VISIBLE); } else { themeBackgroundImg.setVisibility(View.GONE); View rv=findViewById(android.R.id.content); if(rv!=null){ GradientDrawable bg=new GradientDrawable(GradientDrawable.Orientation.TOP_BOTTOM,new int[]{Color.parseColor(c1),Color.parseColor(c2)}); rv.setBackground(bg); } } } }catch(Exception ignored){} }
private void listenToRoomTheme(){ roomMetaRef.addValueEventListener(new ValueEventListener(){ @Override public void onDataChange(@NonNull DataSnapshot s){ String n=s.child("roomTheme").getValue(String.class); String c1=s.child("roomThemeColor1").getValue(String.class); String c2=s.child("roomThemeColor2").getValue(String.class); String img=s.child("roomThemeImage").getValue(String.class); if(n!=null&&!n.isEmpty()&&c1!=null&&c2!=null) applyRoomTheme(c1,c2,n,img!=null?img:"theme_night"); } @Override public void onCancelled(@NonNull DatabaseError e){} }); }
private void showRoomThemeDialog(){ Toast.makeText(this,"Theme - Coming Soon",Toast.LENGTH_SHORT).show(); }
private void showIconToolsDialog(boolean isOwner){ BottomSheetDialog dialog=new BottomSheetDialog(this,R.style.Theme_Design_BottomSheetDialog); LinearLayout root=new LinearLayout(this); root.setOrientation(LinearLayout.VERTICAL); root.setPadding(35,35,35,45); GradientDrawable bg=new GradientDrawable(GradientDrawable.Orientation.TOP_BOTTOM,new int[]{Color.parseColor("#1B1035"),Color.parseColor("#0A0518")}); bg.setCornerRadii(new float[]{45,45,45,45,0,0,0,0}); root.setBackground(bg); TextView title=new TextView(this); title.setText("Basic Tools"); title.setTextColor(Color.parseColor("#FFD700")); title.setTextSize(18); title.setTypeface(null,android.graphics.Typeface.BOLD); title.setPadding(0,0,0,15); root.addView(title); GridLayout grid=new GridLayout(this); grid.setColumnCount(4); grid.setUseDefaultMargins(true); String[][] basic={{"Lock","Lock off"},{"Set","Room set"},{"Edit","Room Edit"},{"Clear","Clear charm"},{"Chat","Clear chat"},{"Mic","Change mic"},{"Theme","Mic Theme"},{"Dress","Dress"},{"Lucky","Lucky Sound"},{"Voice","Voice User"},{"Kick","Kick out record"},{"Reward","Reward Event"}}; for(String[] it:basic){ LinearLayout cell=makeToolIconCell(it[0],it[1],v->{ dialog.dismiss(); handleToolClick(it[1],isOwner); }); grid.addView(cell); } root.addView(grid); dialog.setContentView(root); Window w=dialog.getWindow(); if(w!=null){ w.setLayout(ViewGroup.LayoutParams.MATCH_PARENT,1400); w.setGravity(Gravity.BOTTOM); } dialog.show(); }
private LinearLayout makeToolIconCell(String icon,String label,View.OnClickListener l){ LinearLayout cell=new LinearLayout(this); cell.setOrientation(LinearLayout.VERTICAL); cell.setGravity(Gravity.CENTER); cell.setPadding(10,15,10,15); cell.setOnClickListener(l); GradientDrawable bg=new GradientDrawable(); bg.setColor(Color.parseColor("#2A1B4E")); bg.setCornerRadius(18); cell.setBackground(bg); GridLayout.LayoutParams lp=new GridLayout.LayoutParams(); lp.width=0; lp.height=ViewGroup.LayoutParams.WRAP_CONTENT; lp.columnSpec=GridLayout.spec(GridLayout.UNDEFINED,1f); lp.setMargins(6,6,6,6); cell.setLayoutParams(lp); TextView ic=new TextView(this); ic.setText(icon); ic.setTextSize(20); ic.setGravity(Gravity.CENTER); cell.addView(ic); TextView lb=new TextView(this); lb.setText(label); lb.setTextColor(Color.WHITE); lb.setTextSize(11); lb.setGravity(Gravity.CENTER); lb.setTypeface(null,android.graphics.Typeface.BOLD); cell.addView(lb); return cell; }
private void handleToolClick(String tool,boolean isOwner){ switch(tool){ case "Lock off": showRoomLockPasswordDialog(); break; case "Room set": if(isOwner) showEditRoomDialog(); else Toast.makeText(this,"Only Owner can edit",Toast.LENGTH_SHORT).show(); break; case "Room Edit": if(isOwner) showEditRoomDialog(); else Toast.makeText(this,"Only Owner",Toast.LENGTH_SHORT).show(); break; case "Clear charm": clearCharm(); break; case "Clear chat": messagesRef.removeValue(); chatMessages.clear(); chatAdapter.notifyDataSetChanged(); Toast.makeText(this,"Chat Cleared",Toast.LENGTH_SHORT).show(); break; case "Change mic": Toast.makeText(this,"Change Mic - Select Seat",Toast.LENGTH_SHORT).show(); break; case "Mic Theme": showRoomThemeDialog(); break; case "Dress": Toast.makeText(this,"Dress - Coming",Toast.LENGTH_SHORT).show(); break; case "Lucky Sound": Toast.makeText(this,"Lucky Sound Played",Toast.LENGTH_SHORT).show(); break; case "Voice User": showScrollableOnlineMembersDialog(); break; case "Kick out record": showScrollableOnlineMembersDialog(); break; case "Reward Event": showRewardEventDialog(); break; } }
private void clearCharm(){ databaseReference.child("seats").addListenerForSingleValueEvent(new ValueEventListener(){ @Override public void onDataChange(@NonNull DataSnapshot s){ for(int i=0;i<10;i++) databaseReference.child("seats").child("seat_"+i).child("giftTotal").setValue(0L); Toast.makeText(VoiceRoomActivity.this,"Charm Cleared",Toast.LENGTH_SHORT).show(); } @Override public void onCancelled(@NonNull DatabaseError e){} }); }
private void showRewardEventDialog(){ BottomSheetDialog dialog=new BottomSheetDialog(this,R.style.Theme_Design_BottomSheetDialog); LinearLayout root=new LinearLayout(this); root.setOrientation(LinearLayout.VERTICAL); root.setPadding(35,35,35,45); GradientDrawable bg=new GradientDrawable(GradientDrawable.Orientation.TOP_BOTTOM,new int[]{Color.parseColor("#0A0518"),Color.parseColor("#1B1035")}); bg.setCornerRadii(new float[]{45,45,45,45,0,0,0,0}); root.setBackground(bg); TextView title=new TextView(this); title.setText("Room Reward Event"); title.setTextColor(Color.parseColor("#FFD700")); title.setTextSize(20); title.setTypeface(null,android.graphics.Typeface.BOLD); title.setGravity(Gravity.CENTER); title.setPadding(0,0,0,8); root.addView(title); TextView weeklyTxt=new TextView(this); weeklyTxt.setText("Weekly Contribution - Loading..."); weeklyTxt.setTextColor(Color.WHITE); weeklyTxt.setTextSize(16); weeklyTxt.setTypeface(null,android.graphics.Typeface.BOLD); weeklyTxt.setGravity(Gravity.CENTER); weeklyTxt.setPadding(0,15,0,15); root.addView(weeklyTxt); Button btnClaim=new Button(this); btnClaim.setText("Claim Rewards"); btnClaim.setBackgroundColor(Color.parseColor("#FF4081")); btnClaim.setTextColor(Color.WHITE); btnClaim.setOnClickListener(v->Toast.makeText(this,"Claimed!",Toast.LENGTH_SHORT).show()); root.addView(btnClaim); databaseReference.child("seats").addListenerForSingleValueEvent(new ValueEventListener(){ @Override public void onDataChange(@NonNull DataSnapshot s){ long total=0; for(DataSnapshot ds:s.getChildren()){ Long g=ds.child("giftTotal").getValue(Long.class); if(g!=null) total+=g; } weeklyTxt.setText("Weekly Contribution - "+total); } @Override public void onCancelled(@NonNull DatabaseError e){} }); dialog.setContentView(root); Window w=dialog.getWindow(); if(w!=null){ w.setLayout(ViewGroup.LayoutParams.MATCH_PARENT,1500); w.setGravity(Gravity.BOTTOM); } dialog.show(); }
private void showChatDialog(){ final Dialog chatDialog=new Dialog(VoiceRoomActivity.this,R.style.Theme_Design_BottomSheetDialog); chatDialog.requestWindowFeature(Window.FEATURE_NO_TITLE); chatDialog.setContentView(R.layout.dialog_bottom_chat); Window window=chatDialog.getWindow(); if(window!=null){ window.setLayout(ViewGroup.LayoutParams.MATCH_PARENT,ViewGroup.LayoutParams.WRAP_CONTENT); window.setGravity(Gravity.BOTTOM); window.setSoftInputMode(WindowManager.LayoutParams.SOFT_INPUT_STATE_VISIBLE); } EditText inputMsg=chatDialog.findViewById(R.id.editRoomMessage); Button btnSendMsg=chatDialog.findViewById(R.id.btnSendRoomMessage); if(btnSendMsg!=null&&inputMsg!=null) btnSendMsg.setOnClickListener(view->{ String message=inputMsg.getText().toString().trim(); String userName=prefs.getString("USER_NAME","User"); if(!message.isEmpty()){ String msgId=messagesRef.push().getKey(); if(msgId!=null){ Map<String,Object> m=new HashMap<>(); m.put("senderName",getCorrectBadgeIcon(currentUserId)+userName); m.put("senderId",currentUserId); m.put("message",message); m.put("timestamp",System.currentTimeMillis()); messagesRef.child(msgId).setValue(m); } inputMsg.setText(""); chatDialog.dismiss(); } }); chatDialog.show(); }
private void showPremiumRankingDialog(){ final Dialog rankDialog=new Dialog(this,android.R.style.Theme_Black_NoTitleBar_Fullscreen); rankDialog.requestWindowFeature(Window.FEATURE_NO_TITLE); rankDialog.setContentView(R.layout.dialog_room_ranking); TextView btnClose=rankDialog.findViewById(R.id.btnCloseRanking); if(btnClose!=null) btnClose.setOnClickListener(v->rankDialog.dismiss()); LinearLayout listContainer=rankDialog.findViewById(R.id.rankingListContainer); Runnable loadRank=()->{ userDatabaseRef.orderByChild(rankTab.equals("Wealth")?"sendingCoins":"receivingCoins").limitToLast(20).addValueEventListener(new ValueEventListener(){ @Override public void onDataChange(@NonNull DataSnapshot snap){ rankCache.clear(); for(DataSnapshot ds:snap.getChildren()){ String n=ds.child("name").getValue(String.class); Long c=ds.child(rankTab.equals("Wealth")?"sendingCoins":"receivingCoins").getValue(Long.class); String img=ds.child("profileImage").getValue(String.class); if(n==null) n="User"; rankCache.add(new RankItem(n,c!=null?c:0L,img,ds.getKey())); } Collections.sort(rankCache,(a,b)->Long.compare(b.coins,a.coins)); if(listContainer!=null){ listContainer.removeAllViews(); for(int i=0;i<rankCache.size();i++){ addRankUserRow(listContainer,String.valueOf(i+1),(i+1)+". "+rankCache.get(i).name,rankCache.get(i).coins+" Coins",i==0?"#FFD700":"#FFFFFF"); } } } @Override public void onCancelled(@NonNull DatabaseError e){} }); }; loadRank.run(); rankDialog.show(); }
private void addRankUserRow(LinearLayout container,String rank,String name,String score,String badgeHex){ Context ctx=container.getContext(); LinearLayout row=new LinearLayout(ctx); row.setOrientation(LinearLayout.HORIZONTAL); row.setPadding(20,20,20,20); row.setGravity(Gravity.CENTER_VERTICAL); GradientDrawable rBg=new GradientDrawable(); rBg.setColor(Color.parseColor("#1B1035")); rBg.setCornerRadius(16); row.setBackground(rBg); LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT,ViewGroup.LayoutParams.WRAP_CONTENT); p.setMargins(0,0,0,12); row.setLayoutParams(p); TextView rt=new TextView(ctx); rt.setText("Top "+rank); rt.setTextColor(Color.parseColor(badgeHex)); rt.setTypeface(null,android.graphics.Typeface.BOLD); rt.setMinWidth(90); row.addView(rt); LinearLayout stack=new LinearLayout(ctx); stack.setOrientation(LinearLayout.VERTICAL); stack.setLayoutParams(new LinearLayout.LayoutParams(0,ViewGroup.LayoutParams.WRAP_CONTENT,1.0f)); TextView nt=new TextView(ctx); nt.setText(name); nt.setTextColor(Color.WHITE); stack.addView(nt); TextView st=new TextView(ctx); st.setText(score); st.setTextColor(Color.parseColor("#00E676")); stack.addView(st); row.addView(stack); container.addView(row); }
static class RankItem{ String name; long coins; String image; String uid; RankItem(String n,long c,String i,String u){ name=n; coins=c; image=i; uid=u; } }
private void triggerFlyingGiftAnimation(String giftName){ try{ ViewGroup rv=findViewById(android.R.id.content); if(rv==null) return; final TextView fv=new TextView(this); fv.setText("Gift "+giftName); fv.setTextColor(Color.parseColor("#FFD700")); fv.setTextSize(20); fv.setTypeface(null,android.graphics.Typeface.BOLD); fv.setGravity(Gravity.CENTER); fv.setBackgroundColor(Color.parseColor("#88000000")); fv.setPadding(30,20,30,20); FrameLayout.LayoutParams params=new FrameLayout.LayoutParams(ViewGroup.LayoutParams.WRAP_CONTENT,ViewGroup.LayoutParams.WRAP_CONTENT); params.gravity=Gravity.BOTTOM|Gravity.CENTER_HORIZONTAL; params.setMargins(0,0,0,300); rv.addView(fv,params); TranslateAnimation anim=new TranslateAnimation(Animation.ABSOLUTE,0f,Animation.ABSOLUTE,0f,Animation.ABSOLUTE,0f,Animation.ABSOLUTE,-1000f); anim.setDuration(2000); anim.setFillAfter(true); anim.setAnimationListener(new Animation.AnimationListener(){ @Override public void onAnimationStart(Animation a){} @Override public void onAnimationEnd(Animation a){ rv.removeView(fv); } @Override public void onAnimationRepeat(Animation a){} }); fv.startAnimation(anim); }catch(Exception ignored){} }
private void listenToRoomAdmins(){ adminsRef.addValueEventListener(new ValueEventListener(){ @Override public void onDataChange(@NonNull DataSnapshot s){ roomAdminList.clear(); for(DataSnapshot ds:s.getChildren()) if(Boolean.TRUE.equals(ds.getValue(Boolean.class))) roomAdminList.add(ds.getKey()); } @Override public void onCancelled(@NonNull DatabaseError e){} }); }
private String getCorrectBadgeIcon(String uid){ if(uid==null||uid.isEmpty()) return ""; if(uid.equals(roomOwnerId)||roomAdminList.contains(uid)) return "Admin "; return ""; }
private void listenToRealtimeChatMessages(){ messagesRef.addChildEventListener(new ChildEventListener(){ @Override public void onChildAdded(@NonNull DataSnapshot snap,@Nullable String prev){ String sn=snap.child("senderName").getValue(String.class); String msg=snap.child("message").getValue(String.class); Long t=snap.child("timestamp").getValue(Long.class); if(t!=null&&t<roomJoinTimestamp) return; if(sn!=null&&msg!=null){ String full=sn+": "+msg; if(!chatMessages.contains(full)){ chatMessages.add(full); chatAdapter.notifyDataSetChanged(); if(chatListView!=null) chatListView.setSelection(chatMessages.size()-1); } } } @Override public void onChildChanged(@NonNull DataSnapshot s,@Nullable String p){} @Override public void onChildRemoved(@NonNull DataSnapshot s){ chatMessages.clear(); chatAdapter.notifyDataSetChanged(); } @Override public void onChildMoved(@NonNull DataSnapshot s,@Nullable String p){} @Override public void onCancelled(@NonNull DatabaseError e){} }); }
private void showRoomLockPasswordDialog(){ AlertDialog.Builder b=new AlertDialog.Builder(VoiceRoomActivity.this); b.setTitle("Room Lock"); LinearLayout layout=new LinearLayout(VoiceRoomActivity.this); layout.setOrientation(LinearLayout.VERTICAL); layout.setPadding(50,30,50,30); final EditText input=new EditText(VoiceRoomActivity.this); input.setHint("Enter Room Password..."); input.setInputType(android.text.InputType.TYPE_CLASS_NUMBER|android.text.InputType.TYPE_NUMBER_VARIATION_PASSWORD); layout.addView(input); b.setView(layout); b.setPositiveButton("Lock Room",(d,w)->{ String pw=input.getText().toString().trim(); if(!pw.isEmpty()){ roomMetaRef.child("roomPassword").setValue(pw); roomMetaRef.child("isLocked").setValue(true); Toast.makeText(this,"Room locked!",Toast.LENGTH_SHORT).show(); } }); b.setNeutralButton("Unlock Room",(d,w)->{ roomMetaRef.child("roomPassword").removeValue(); roomMetaRef.child("isLocked").setValue(false); Toast.makeText(this,"Room Unlocked!",Toast.LENGTH_SHORT).show(); }); b.setNegativeButton("Cancel",(d,w)->d.cancel()); b.show(); }
private void showScrollableOnlineMembersDialog(){ Toast.makeText(this,"Online Members - Loading",Toast.LENGTH_SHORT).show(); showPremiumRoomInfoAndMembersDialog(); }
private void syncLatestUserProfile(){ if(!currentUserId.isEmpty()) userDatabaseRef.child(currentUserId).addListenerForSingleValueEvent(new ValueEventListener(){ @Override public void onDataChange(@NonNull DataSnapshot s){ if(s.exists()){ String dbName=s.child("name").getValue(String.class); String dbImg=s.child("profileImage").getValue(String.class); SharedPreferences.Editor e=prefs.edit(); if(dbName!=null&&!dbName.isEmpty()) e.putString("USER_NAME",dbName); if(dbImg!=null){ e.putString("USER_IMAGE",dbImg); e.putString("USER_PROFILE_IMAGE",dbImg); } e.apply(); } } @Override public void onCancelled(@NonNull DatabaseError e){} }); }
private void listenToRoomDetails(){ roomMetaRef.addValueEventListener(new ValueEventListener(){ @Override public void onDataChange(@NonNull DataSnapshot s){ String rn=s.child("roomName").getValue(String.class); String rb=s.child("roomBio").getValue(String.class); String oi=s.child("roomOwnerImage").getValue(String.class); if(rn!=null&&!rn.isEmpty()){ if(roomTitleText!=null) roomTitleText.setText(rn); } else if(roomTitleText!=null) roomTitleText.setText("SR Voice Room"); if(roomInfoText!=null) roomInfoText.setText("ID: "+roomOwnerId); if(roomNoticeBarText!=null){ String bio=(rb!=null&&!rb.isEmpty())?rb:"Welcome to my voice room!"; roomNoticeBarText.setText("Notice: "+bio); } if(roomHeaderProfileImg!=null&&oi!=null&&!oi.isEmpty()){ try{ byte[] d=android.util.Base64.decode(oi,android.util.Base64.DEFAULT); Bitmap bmp=BitmapFactory.decodeByteArray(d,0,d.length); if(bmp!=null){ RoundedBitmapDrawable rd=RoundedBitmapDrawableFactory.create(getResources(),bmp); rd.setCircular(true); roomHeaderProfileImg.setImageDrawable(rd); } }catch(Exception e){ roomHeaderProfileImg.setImageResource(android.R.drawable.ic_menu_my_calendar); } } } @Override public void onCancelled(@NonNull DatabaseError e){} }); }
private void showEditRoomDialog(){ AlertDialog.Builder b=new AlertDialog.Builder(VoiceRoomActivity.this); b.setTitle("Room Settings"); LinearLayout layout=new LinearLayout(VoiceRoomActivity.this); layout.setOrientation(LinearLayout.VERTICAL); layout.setPadding(50,20,50,20); Button btnPic=new Button(VoiceRoomActivity.this); btnPic.setText("Change Room Profile Picture"); btnPic.setOnClickListener(v->{ Intent intent=new Intent(Intent.ACTION_PICK,MediaStore.Images.Media.EXTERNAL_CONTENT_URI); startActivityForResult(intent,PICK_IMAGE_REQUEST); }); layout.addView(btnPic); dialogInputName=new EditText(VoiceRoomActivity.this); dialogInputName.setHint("Enter Room Name..."); layout.addView(dialogInputName); dialogInputBio=new EditText(VoiceRoomActivity.this); dialogInputBio.setHint("Enter Room Bio..."); layout.addView(dialogInputBio); b.setView(layout); b.setPositiveButton("Save",(d,w)->{ String nn=dialogInputName.getText().toString().trim(); String nb=dialogInputBio.getText().toString().trim(); if(!nn.isEmpty()) roomMetaRef.child("roomName").setValue(nn); if(!nb.isEmpty()) roomMetaRef.child("roomBio").setValue(nb); Toast.makeText(this,"Room settings updated!",Toast.LENGTH_SHORT).show(); }); b.setNegativeButton("Cancel",(d,w)->d.cancel()); b.show(); }
@Override protected void onActivityResult(int requestCode,int resultCode,@Nullable Intent data){ super.onActivityResult(requestCode,resultCode,data); if(requestCode==PICK_IMAGE_REQUEST&&resultCode==RESULT_OK&&data!=null&&data.getData()!=null){ Uri uri=data.getData(); try{ InputStream is=getContentResolver().openInputStream(uri); Bitmap bmp=BitmapFactory.decodeStream(is); if(bmp!=null){ Bitmap resized=Bitmap.createScaledBitmap(bmp,150,150,true); ByteArrayOutputStream baos=new ByteArrayOutputStream(); resized.compress(Bitmap.CompressFormat.JPEG,70,baos); String enc=android.util.Base64.encodeToString(baos.toByteArray(),android.util.Base64.DEFAULT); roomMetaRef.child("roomOwnerImage").setValue(enc); Toast.makeText(this,"Room Profile Picture Updated!",Toast.LENGTH_SHORT).show(); } }catch(Exception e){ Toast.makeText(this,"Failed to load image",Toast.LENGTH_SHORT).show(); } } }
private void listenToOnlineMembers(){ String un=prefs.getString("USER_NAME","User"); databaseReference.child("online_users").child(currentUserId).setValue(un); databaseReference.child("online_users").child(currentUserId).onDisconnect().removeValue(); databaseReference.child("online_users").addValueEventListener(new ValueEventListener(){ @Override public void onDataChange(@NonNull DataSnapshot s){ long c=s.getChildrenCount(); if(textOnlineCount!=null) textOnlineCount.setText(String.valueOf(c)); } @Override public void onCancelled(@NonNull DatabaseError e){} }); }
private void showPremiumRoomInfoAndMembersDialog(){ BottomSheetDialog dialog=new BottomSheetDialog(this,R.style.Theme_Design_BottomSheetDialog); LinearLayout root=new LinearLayout(this); root.setOrientation(LinearLayout.VERTICAL); root.setPadding(40,40,40,40); GradientDrawable bg=new GradientDrawable(GradientDrawable.Orientation.TOP_BOTTOM,new int[]{Color.parseColor("#1B1035"),Color.parseColor("#0A0518")}); bg.setCornerRadii(new float[]{45,45,45,45,0,0,0,0}); root.setBackground(bg); TextView title=new TextView(this); title.setText("Room Info - ID: "+roomOwnerId); title.setTextColor(Color.parseColor("#FFD700")); title.setTextSize(18); title.setTypeface(null,android.graphics.Typeface.BOLD); title.setGravity(Gravity.CENTER); title.setPadding(0,0,0,20); root.addView(title); Button btnReward=new Button(this); btnReward.setText("Reward Event - Weekly Claim"); btnReward.setBackgroundColor(Color.parseColor("#FFD700")); btnReward.setTextColor(Color.BLACK); btnReward.setOnClickListener(v->{ dialog.dismiss(); showRewardEventDialog(); }); root.addView(btnReward); Button btnClose=new Button(this); btnClose.setText("Close"); btnClose.setOnClickListener(v->dialog.dismiss()); root.addView(btnClose); dialog.setContentView(root); Window w=dialog.getWindow(); if(w!=null){ w.setLayout(ViewGroup.LayoutParams.MATCH_PARENT,1200); w.setGravity(Gravity.BOTTOM); } dialog.show(); }
private void listenToFirebaseSeats(){ int[] imgIds={R.id.seatImg1,R.id.seatImg2,R.id.seatImg3,R.id.seatImg4,R.id.seatImg5,R.id.seatImg6,R.id.seatImg7,R.id.seatImg8,R.id.seatImg9,R.id.seatImg10}; int[] txtIds={R.id.seatTxt1,R.id.seatTxt2,R.id.seatTxt3,R.id.seatTxt4,R.id.seatTxt5,R.id.seatTxt6,R.id.seatTxt7,R.id.seatTxt8,R.id.seatTxt9,R.id.seatTxt10}; int[] giftIds={R.id.seatGiftTxt1,R.id.seatGiftTxt2,R.id.seatGiftTxt3,R.id.seatGiftTxt4,R.id.seatGiftTxt5,R.id.seatGiftTxt6,R.id.seatGiftTxt7,R.id.seatGiftTxt8,R.id.seatGiftTxt9,R.id.seatGiftTxt10}; databaseReference.child("seats").addValueEventListener(new ValueEventListener(){ @Override public void onDataChange(@NonNull DataSnapshot snap){ for(int i=0;i<10;i++){ ImageView si=findViewById(imgIds[i]); TextView st=findViewById(txtIds[i]); TextView sg=findViewById(giftIds[i]); String k="seat_"+i; if(snap.hasChild(k)){ String name=snap.child(k).child("userName").getValue(String.class); String imgB=snap.child(k).child("userImage").getValue(String.class); String suid=snap.child(k).child("userId").getValue(String.class); Long gt=snap.child(k).child("giftTotal").getValue(Long.class); if(st!=null){ String ri=(suid!=null&&(suid.equals(roomOwnerId)||roomAdminList.contains(suid)))?"Admin ":""; String dn=(name!=null&&!name.isEmpty())?name:(i==0?"Host":String.valueOf(i+1)); st.setText(ri+dn); } if(sg!=null) sg.setText((gt!=null&&gt>0)?gt+" Coins":""); if(si!=null&&imgB!=null&&!imgB.isEmpty()){ try{ byte[] d=android.util.Base64.decode(imgB,android.util.Base64.DEFAULT); Bitmap bmp=BitmapFactory.decodeByteArray(d,0,d.length); if(bmp!=null){ RoundedBitmapDrawable rd=RoundedBitmapDrawableFactory.create(getResources(),bmp); rd.setCircular(true); si.setImageDrawable(rd); si.setPadding(0,0,0,0); } }catch(Exception e){ si.setImageResource(android.R.drawable.ic_menu_my_calendar); } } } else { if(st!=null) st.setText(i==0?"Host":String.valueOf(i+1)); if(sg!=null) sg.setText(""); if(si!=null){ si.setImageResource(android.R.drawable.ic_menu_my_calendar); si.setPadding(12,12,12,12); } } } } @Override public void onCancelled(@NonNull DatabaseError e){} }); }
private void setupSeatInteractions(){ int[] cardIds={R.id.seatCard1,R.id.seatCard2,R.id.seatCard3,R.id.seatCard4,R.id.seatCard5,R.id.seatCard6,R.id.seatCard7,R.id.seatCard8,R.id.seatCard9,R.id.seatCard10}; for(int i=0;i<cardIds.length;i++){ final int idx=i; final int num=i+1; View c=findViewById(cardIds[i]); if(c!=null) c.setOnClickListener(v->{ String k="seat_"+idx; databaseReference.child("seats").child(k).addListenerForSingleValueEvent(new ValueEventListener(){ @Override public void onDataChange(@NonNull DataSnapshot snap){ String on=snap.child("userName").getValue(String.class); String ou=snap.child("userId").getValue(String.class); boolean occ=on!=null&&!on.isEmpty(); List<String> opts=new ArrayList<>(); if(occ){ opts.add("View Profile (ID: "+ou+")"); opts.add("Leave Mic"); } else opts.add("Take Mic"); opts.add("Cancel"); CharSequence[] arr=opts.toArray(new CharSequence[0]); AlertDialog.Builder b=new AlertDialog.Builder(VoiceRoomActivity.this); b.setTitle("Seat "+num); b.setItems(arr,(d,w)->{ String sel=arr[w].toString(); if(sel.contains("Take Mic")) takeSeat(idx,k); else if(sel.contains("View Profile")){ String imgU=snap.child("userImage").getValue(String.class); fetchUserDataAndShowProfile(on,ou,imgU); } else if(sel.contains("Leave Mic")){ databaseReference.child("seats").child(k).removeValue(); Toast.makeText(VoiceRoomActivity.this,"Left seat",Toast.LENGTH_SHORT).show(); } }); b.show(); } @Override public void onCancelled(@NonNull DatabaseError e){} }); }); } }
private void takeSeat(int seatIndex,String seatKey){ final String userName=prefs.getString("USER_NAME","User"); final String userImageUriStr=prefs.getString("USER_PROFILE_IMAGE",prefs.getString("USER_IMAGE","")); for(int i=0;i<10;i++){ final int oldIndex=i; databaseReference.child("seats").child("seat_"+i).addListenerForSingleValueEvent(new ValueEventListener(){ @Override public void onDataChange(@NonNull DataSnapshot s){ String sUserId=s.child("userId").getValue(String.class); if(sUserId!=null&&sUserId.equals(currentUserId)) databaseReference.child("seats").child("seat_"+oldIndex).removeValue(); } @Override public void onCancelled(@NonNull DatabaseError e){} }); } databaseReference.child("seats").child(seatKey).child("userId").setValue(currentUserId); databaseReference.child("seats").child(seatKey).child("userName").setValue(userName); databaseReference.child("seats").child(seatKey).child("userImage").setValue(userImageUriStr); databaseReference.child("seats").child(seatKey).child("giftTotal").setValue(0L); databaseReference.child("seats").child(seatKey).onDisconnect().removeValue(); Toast.makeText(VoiceRoomActivity.this,"Joined seat successfully!",Toast.LENGTH_SHORT).show(); }
private void fetchUserDataAndShowProfile(String un,String uid,String img){ if(uid==null||uid.isEmpty()){ showUserProfileDialog(un,uid,img,0L,0L,"M","BD"); return; } userDatabaseRef.child(uid).addListenerForSingleValueEvent(new ValueEventListener(){ @Override public void onDataChange(@NonNull DataSnapshot s){ long send=0L; long recv=0L; String gender="M"; String country="BD"; if(s.exists()){ Long a=s.child("sendingCoins").getValue(Long.class); Long b=s.child("receivingCoins").getValue(Long.class); String dg=s.child("gender").getValue(String.class); String dc=s.child("country").getValue(String.class); if(a!=null) send=a; if(b!=null) recv=b; if(dg!=null){ String lo=dg.toLowerCase(); if(lo.contains("female")||lo.contains("girl")) gender="F"; } if(dc!=null&&!dc.isEmpty()) country=dc; } showUserProfileDialog(un,uid,img,send,recv,gender,country); } @Override public void onCancelled(@NonNull DatabaseError e){ showUserProfileDialog(un,uid,img,0L,0L,"M","BD"); } }); }
private void showUserProfileDialog(String un,String uid,String img,long send,long recv,String gender,String country){ BottomSheetDialog d=new BottomSheetDialog(this,R.style.Theme_Design_BottomSheetDialog); LinearLayout layout=new LinearLayout(this); layout.setOrientation(LinearLayout.VERTICAL); layout.setPadding(40,50,40,60); GradientDrawable bg=new GradientDrawable(GradientDrawable.Orientation.TOP_BOTTOM,new int[]{Color.parseColor("#2A1B4E"),Color.parseColor("#0A0518")}); bg.setCornerRadii(new float[]{60,60,60,60,0,0,0,0}); layout.setBackground(bg); ImageView big=new ImageView(this); LinearLayout.LayoutParams ip=new LinearLayout.LayoutParams(340,340); ip.gravity=Gravity.CENTER_HORIZONTAL; ip.setMargins(0,0,0,20); big.setLayoutParams(ip); big.setScaleType(ImageView.ScaleType.CENTER_CROP); if(img!=null&&!img.isEmpty()){ try{ byte[] b=android.util.Base64.decode(img,android.util.Base64.DEFAULT); Bitmap bmp=BitmapFactory.decodeByteArray(b,0,b.length); if(bmp!=null){ RoundedBitmapDrawable rd=RoundedBitmapDrawableFactory.create(getResources(),bmp); rd.setCircular(true); big.setImageDrawable(rd); } else big.setImageResource(android.R.drawable.ic_menu_my_calendar); }catch(Exception e){ big.setImageResource(android.R.drawable.ic_menu_my_calendar); } } else big.setImageResource(android.R.drawable.ic_menu_my_calendar); layout.addView(big); TextView nt=new TextView(this); nt.setText((un!=null?un:"SR User")+" "+gender+" "+country); nt.setTextColor(Color.WHITE); nt.setTextSize(22); nt.setTypeface(null,android.graphics.Typeface.BOLD); nt.setGravity(Gravity.CENTER); nt.setPadding(0,0,0,8); layout.addView(nt); String did=(uid!=null&&!uid.isEmpty())?uid:"493859069"; TextView idT=new TextView(this); idT.setText("ID: "+did); idT.setTextColor(Color.parseColor("#00E676")); idT.setTextSize(16); idT.setGravity(Gravity.CENTER); idT.setPadding(0,0,0,12); idT.setOnClickListener(v->{ ClipboardManager cm=(ClipboardManager)getSystemService(Context.CLIPBOARD_SERVICE); ClipData clip=ClipData.newPlainText("User ID",did); if(cm!=null){ cm.setPrimaryClip(clip); Toast.makeText(this,"ID Copied: "+did,Toast.LENGTH_SHORT).show(); } }); layout.addView(idT); int sl=LevelUtils.calculateLevel(send); int rl=LevelUtils.calculateLevel(recv); LinearLayout lr=new LinearLayout(this); lr.setOrientation(LinearLayout.HORIZONTAL); lr.setGravity(Gravity.CENTER); lr.setPadding(0,0,0,20); lr.addView(createSoftBadgeView("Send Lv."+sl,LevelUtils.getLevelColor(sl))); lr.addView(createSoftBadgeView("Recv Lv."+rl,LevelUtils.getLevelColor(rl))); layout.addView(lr); LinearLayout ar=new LinearLayout(this); ar.setOrientation(LinearLayout.HORIZONTAL); ar.setGravity(Gravity.CENTER); Button bf=new Button(this); bf.setText("Follow"); bf.setBackgroundColor(Color.parseColor("#FFD700")); bf.setTextColor(Color.BLACK); bf.setTypeface(null,android.graphics.Typeface.BOLD); LinearLayout.LayoutParams p1=new LinearLayout.LayoutParams(0,130,1.0f); p1.setMargins(0,0,8,0); bf.setLayoutParams(p1); bf.setOnClickListener(v->{ if(uid==null||uid.equals(currentUserId)){ Toast.makeText(this,"You cannot follow yourself!",Toast.LENGTH_SHORT).show(); return; } userDatabaseRef.child(uid).child("followers").child(currentUserId).setValue(true); userDatabaseRef.child(currentUserId).child("following").child(uid).setValue(true); bf.setText("Following"); Toast.makeText(this,"Followed "+un,Toast.LENGTH_SHORT).show(); }); ar.addView(bf); Button bgift=new Button(this); bgift.setText("Gift"); bgift.setBackgroundColor(Color.parseColor("#FF4081")); bgift.setTextColor(Color.WHITE); bgift.setTypeface(null,android.graphics.Typeface.BOLD); LinearLayout.LayoutParams p2=new LinearLayout.LayoutParams(0,130,1.0f); p2.setMargins(8,0,0,0); bgift.setLayoutParams(p2); bgift.setOnClickListener(v->{ d.dismiss(); showNewGiftPanel(); }); ar.addView(bgift); layout.addView(ar); Button bfull=new Button(this); bfull.setText("Full Profile"); bfull.setBackgroundColor(Color.parseColor("#2A1B4E")); bfull.setTextColor(Color.parseColor("#FFD700")); LinearLayout.LayoutParams pv=new LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT,120); pv.setMargins(0,15,0,0); bfull.setLayoutParams(pv); bfull.setOnClickListener(v->{ d.dismiss(); showFullProfileInside(un,uid,img,send,recv,gender,country); }); layout.addView(bfull); d.setContentView(layout); Window w=d.getWindow(); if(w!=null){ w.setLayout(ViewGroup.LayoutParams.MATCH_PARENT,1750); w.setGravity(Gravity.BOTTOM); } d.show(); }
private void showFullProfileInside(String un,String uid,String img,long send,long recv,String gender,String country){ BottomSheetDialog d=new BottomSheetDialog(this,R.style.Theme_Design_BottomSheetDialog); LinearLayout layout=new LinearLayout(this); layout.setOrientation(LinearLayout.VERTICAL); layout.setPadding(40,40,40,60); GradientDrawable bg=new GradientDrawable(GradientDrawable.Orientation.TOP_BOTTOM,new int[]{Color.parseColor("#1B1035"),Color.parseColor("#0A0518")}); bg.setCornerRadii(new float[]{45,45,45,45,0,0,0,0}); layout.setBackground(bg); TextView title=new TextView(this); title.setText("Full Profile - "+un); title.setTextColor(Color.parseColor("#FFD700")); title.setTextSize(19); title.setTypeface(null,android.graphics.Typeface.BOLD); title.setGravity(Gravity.CENTER); title.setPadding(0,0,0,20); layout.addView(title); TextView info=new TextView(this); info.setText("ID: "+uid+"\nGender: "+gender+" Country: "+country+"\nSend Level: "+LevelUtils.calculateLevel(send)+" Recv Level: "+LevelUtils.calculateLevel(recv)); info.setTextColor(Color.WHITE); info.setTextSize(15); info.setGravity(Gravity.CENTER); info.setPadding(0,0,0,20); layout.addView(info); Button bc=new Button(this); bc.setText("Back to Room"); bc.setBackgroundColor(Color.parseColor("#FFD700")); bc.setTextColor(Color.BLACK); bc.setOnClickListener(v->d.dismiss()); layout.addView(bc); d.setContentView(layout); Window w=d.getWindow(); if(w!=null){ w.setLayout(ViewGroup.LayoutParams.MATCH_PARENT,1600); w.setGravity(Gravity.BOTTOM); } d.show(); }
private View createSoftBadgeView(String text,int colorInt){ TextView badge=new TextView(this); badge.setText(text); badge.setTextColor(Color.WHITE); badge.setTextSize(12); badge.setTypeface(null,android.graphics.Typeface.BOLD); badge.setPadding(22,10,22,10); GradientDrawable bg=new GradientDrawable(); bg.setColor(colorInt); bg.setCornerRadius(30); badge.setBackground(bg); LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(ViewGroup.LayoutParams.WRAP_CONTENT,ViewGroup.LayoutParams.WRAP_CONTENT); lp.setMargins(0,0,16,0); badge.setLayoutParams(lp); return badge; }
private void showFullLevelCenterDialog(){ BottomSheetDialog dialog=new BottomSheetDialog(this,R.style.Theme_Design_BottomSheetDialog); LinearLayout root=new LinearLayout(this); root.setOrientation(LinearLayout.VERTICAL); root.setPadding(35,35,35,35); GradientDrawable bg=new GradientDrawable(GradientDrawable.Orientation.TOP_BOTTOM,new int[]{Color.parseColor("#1B1035"),Color.parseColor("#0A0518")}); bg.setCornerRadii(new float[]{45,45,45,45,0,0,0,0}); root.setBackground(bg); TextView title=new TextView(this); title.setText("SR Level Center (Lv.1 - Lv.150)"); title.setTextColor(Color.parseColor("#FFD700")); title.setTextSize(18); title.setTypeface(null,android.graphics.Typeface.BOLD); title.setGravity(Gravity.CENTER); title.setPadding(0,0,0,20); root.addView(title); ScrollView scrollView=new ScrollView(this); scrollView.setLayoutParams(new LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT,1400)); scrollView.setFillViewport(true); LinearLayout listContainer=new LinearLayout(this); listContainer.setOrientation(LinearLayout.VERTICAL); for(int lvl=1;lvl<=150;lvl++){ LinearLayout row=new LinearLayout(this); row.setOrientation(LinearLayout.HORIZONTAL); row.setPadding(25,20,25,20); row.setGravity(Gravity.CENTER_VERTICAL); GradientDrawable rBg=new GradientDrawable(); rBg.setColor(Color.parseColor("#2A1B4E")); rBg.setCornerRadius(20); row.setBackground(rBg); LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT,ViewGroup.LayoutParams.WRAP_CONTENT); p.setMargins(0,0,0,14); row.setLayoutParams(p); TextView badge=new TextView(this); badge.setText(LevelUtils.getLevelBadgeText(lvl)); badge.setTextColor(Color.WHITE); badge.setTextSize(14); badge.setTypeface(null,android.graphics.Typeface.BOLD); badge.setGravity(Gravity.CENTER); badge.setPadding(20,12,20,12); GradientDrawable bBg=new GradientDrawable(); bBg.setColor(LevelUtils.getLevelColor(lvl)); bBg.setCornerRadius(25); badge.setBackground(bBg); badge.setMinWidth(110); row.addView(badge); TextView targetTxt=new TextView(this); targetTxt.setText("Level "+lvl+" - Target: "+LevelUtils.getLevelTargetCoinsFormatted(lvl)); targetTxt.setTextColor(Color.parseColor("#00E676")); targetTxt.setTextSize(13); targetTxt.setPadding(20,0,0,0); row.addView(targetTxt); listContainer.addView(row); } scrollView.addView(listContainer); root.addView(scrollView); dialog.setContentView(root); Window window=dialog.getWindow(); if(window!=null){ window.setLayout(ViewGroup.LayoutParams.MATCH_PARENT,1600); window.setGravity(Gravity.BOTTOM); } dialog.show(); }
